CREATE TABLE ingredient_catalog (
  id TEXT PRIMARY KEY,
  category TEXT,
  user_created INTEGER NOT NULL DEFAULT 0 CHECK (user_created IN (0, 1)),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE TABLE ingredient_catalog_names (
  ingredient_id TEXT NOT NULL REFERENCES ingredient_catalog(id) ON DELETE CASCADE,
  locale TEXT NOT NULL,
  display_name TEXT NOT NULL,
  normalized_name TEXT NOT NULL,
  preferred INTEGER NOT NULL DEFAULT 1 CHECK (preferred IN (0, 1)),
  PRIMARY KEY (ingredient_id, locale, normalized_name),
  UNIQUE (locale, normalized_name)
);

CREATE INDEX ingredient_catalog_names_search ON ingredient_catalog_names(normalized_name, locale);
ALTER TABLE ingredients ADD COLUMN catalog_id TEXT REFERENCES ingredient_catalog(id);
CREATE INDEX ingredients_catalog_id ON ingredients(catalog_id);


